import{_ as d,l as i,o as e,c as f,v as t,p as l,x as r,d as o,i as s,S as n}from"./chunks/framework.InCnrqk-.js";const A=JSON.parse('{"title":"FFN 扩展比","description":"","frontmatter":{"title":"FFN 扩展比","date":"2026-09-07T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/ffn-expansion-ratio.md","filePath":"llm/ffn-expansion-ratio.md","lastUpdated":1789023840000}'),h={name:"llm/ffn-expansion-ratio.md"};function p(_,a,c,F,E,B){const m=i("Mermaid");return e(),f("div",null,[a[1]||(a[1]=t('<h1 id="ffn-扩展比" tabindex="-1">FFN 扩展比 <a class="header-anchor" href="#ffn-扩展比" aria-label="Permalink to &quot;FFN 扩展比&quot;">​</a></h1><div class="epigraph"><p>前馈子层是两层线性变换夹一个激活；输入输出宽 $d_{\\mathrm{model}}=512$，中间宽 $d_{\\mathrm{ff}}=2048$，四倍扩展是默认容量。</p><footer>—— 据 Vaswani et al., Attention Is All You Need, NeurIPS 2017 整理</footer></div><p><a href="/llm/transformer-block-compose">上一课</a>把块收成「注意力增量加前馈增量」，并声明 FFN 是逐位置的。本课不重讲块的组成，也不写注意力公式。缺口是：逐位置的那张 MLP 中间要扩多宽。Vaswani 取四倍；后来的门控线性（SwiGLU 一类）因为多一路投影，往往把中间宽改成约 \\(\\frac{8}{3}d\\)，使总参数仍与四倍 ReLU FFN 大致相当。扩展比是容量旋钮，不是又一种块。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><a href="/llm/transformer-block-compose">Transformer 块：注意力加前馈</a>只要求 FFN 输出与流同宽。若中间层也是 \\(d_{\\mathrm{model}}\\)，非线性发生在与总线相同的维度里，能分开的特征方向受 \\(d\\) 限制，而总线还要同时承载注意力写来的混合结果。扩宽再缩回，等于在位置内部租用一段临时的高维工作区，算完再投影回流——残差协议不许把总线本身改宽，只能在 \\(F\\) 内部暂扩。</p><p>扩多少是预算问题。中间宽 \\(d_{\\mathrm{ff}}\\) 带来约 \\(2\\,d\\,d_{\\mathrm{ff}}\\) 的参数（两张矩阵），在块内常常与注意力投影同量级甚至更大。扩到八倍、十倍，逐位置容量上去，显存与算力也上去，且收益递减。扩得不够，块只是注意力在换位置，位置内几乎做不成新的特征。四倍是原论文的工作点，不是定理；但后文谈「标准块」时，四倍就是那个工作点。</p><h3 id="门控改变的是「有效宽度」的记账" tabindex="-1">门控改变的是「有效宽度」的记账 <a class="header-anchor" href="#门控改变的是「有效宽度」的记账" aria-label="Permalink to &quot;门控改变的是「有效宽度」的记账&quot;">​</a></h3><p>SwiGLU 一类把升维拆成两路：一路经激活当门，一路当值，逐元相乘后再降维。参数变成约 \\(3\\,d\\,d_{\\mathrm{ff}}\\)（三张 \\(d\\times d_{\\mathrm{ff}}\\) 量级的矩阵，具体实现常把两路升维合成一次）。若仍取 \\(d_{\\mathrm{ff}}=4d\\)，块会明显比 ReLU 四倍更贵。常见补偿是令 \\(d_{\\mathrm{ff}}\\approx \\frac{2}{3}\\times 4d=\\frac{8}{3}d\\)，使参数回到四倍 ReLU 附近。比较扩展比时必须声明激活族；只说「四倍」会把 SwiGLU 的中间宽说错。</p><p><span class="marginnote">本课不讲 GeLU 与 SiLU 的曲线形状，那是激活课序。这里只记账：有没有额外的门控投影，以及为了对齐参数该怎么改 \\(d_{\\mathrm{ff}}\\)。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>标准 ReLU（或 GeLU）FFN 为</p> \\[\\mathrm{FFN}(x)=\\sigma(x W_1) W_2, \\]<p>\\(W_1\\in\\mathbb{R}^{d\\times d_{\\mathrm{ff}}}\\)，\\(W_2\\in\\mathbb{R}^{d_{\\mathrm{ff}}\\times d}\\)，偏置可有可无。\\(\\sigma\\) 逐元。每个位置独立乘这两张矩阵。Vaswani 取 \\(d_{\\mathrm{ff}}=4d\\)。SwiGLU 写作 \\(\\bigl(\\sigma(x W_g)\\odot (x W_u)\\bigr) W_2\\)，中间宽按参数对齐常取 \\(\\frac{8}{3}d\\)，并凑成硬件友好的倍数（例如 256 的倍数）。</p><p>选择 \\(d_{\\mathrm{ff}}\\) 的经验做法与选 \\(|V|\\) 类似：在块参数预算内扫一两个工作点，看损失。宽度必须整除或对齐到内核友好的尺寸，否则吞吐崩掉，那是实现约束，不是模型约束。MoE 把 \\(d_{\\mathrm{ff}}\\) 乘专家数再按路由稀疏激活，有效计算宽度与参数宽度分开，那是后课；稠密块里两者是一回事。</p><h3 id="扩展发生在-内-不发生在流上" tabindex="-1">扩展发生在 \\(F\\) 内，不发生在流上 <a class="header-anchor" href="#扩展发生在-内-不发生在流上" aria-label="Permalink to &quot;扩展发生在 $F$ 内，不发生在流上&quot;">​</a></h3><p>中间激活的形状是 \\(n\\times d_{\\mathrm{ff}}\\)，只存在于该子层的前向与反传。写回流时必须回到 \\(d\\)。因此扩展比不改变 <a href="/llm/residual-stream">残差流</a> 的位宽，也不改变嵌入表的 \\(|V|\\times d\\)。它改变的是：每个位置、每一块，有多少临时方向用来做非线性分离。注意力的头维之和仍是 \\(d\\)，与 \\(d_{\\mathrm{ff}}\\) 无强制关系；可以独立调，只是总预算要一起看。</p><p><span class="marginnote">训练时 \\(n\\times d_{\\mathrm{ff}}\\) 的激活往往是显存大户，甚至超过参数本身。推理若用量化或融合核，中间宽的代价主要是算力。同一扩展比在训练与推理上的瓶颈可以不同。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>高维中间层让 \\(\\sigma\\) 可以在很多方向上把空间折弯，再由 \\(W_2\\) 挑选哪些弯折值得写回流。四倍意味着临时工作区是总线的四倍，写回是一次压缩。压缩会丢弃中间方向：这是容量，也是瓶颈。解释里有时把 FFN 看成键值记忆——中间单元对某些流方向点火，对应的 \\(W_2\\) 行写入固定向量。扩展比就是这张记忆有多少槽；本课不把记忆解释做完，只指出槽数由 \\(d_{\\mathrm{ff}}\\) 决定。</p><p>与注意力的分工因此更具体：注意力决定从哪些位置借内容，FFN 决定在本位置用多大的工作区加工。工作区太小，借来的内容无法被非线性拆开；工作区太大，块参数被 FFN 主导，注意力相对变瘦（若总预算固定）。原论文在 \\(d=512\\) 时给 FFN 四倍、注意力八头，是一套搭配，不是两条独立定律。</p><h3 id="参数对齐的算术" tabindex="-1">参数对齐的算术 <a class="header-anchor" href="#参数对齐的算术" aria-label="Permalink to &quot;参数对齐的算术&quot;">​</a></h3><p>ReLU 四倍：两张矩阵，\\(2\\times d\\times 4d=8d^2\\)。SwiGLU 若中间宽仍为 \\(4d\\) 且三路满配，约 \\(12d^2\\)，贵一半。把中间宽降到 \\(\\frac{8}{3}d\\)：\\(3\\times d\\times \\frac{8}{3}d=8d^2\\)，与 ReLU 四倍对齐。这就是「SwiGLU 宽度」在文献里常显得不是整数倍的原因——比的是参数，不是 \\(d_{\\mathrm{ff}}/d\\) 这个整数。写配置时应同时给出激活类型与 \\(d_{\\mathrm{ff}}\\) 的绝对数。</p><p><span class="marginnote">不要在 GQA 或 FlashAttention 里回头讲扩展比。那些课假定块已经组成、FFN 已经有宽度。本课也不要去讲 KV 字节。</span></p>',23)),(e(),l(n,null,{default:r(()=>[s(m,{id:"mermaid-65",class:"mermaid",graph:"flowchart%20TD%0A%20%20X%5B%22%E4%BD%8D%E7%BD%AE%E4%B8%8A%E7%9A%84%20d%20%E7%BB%B4%E6%B5%81%22%5D%20--%3E%20UP%5B%22%E5%8D%87%E7%BB%B4%E5%88%B0%20d_ff%22%5D%0A%20%20UP%20--%3E%20ACT%5B%22%E9%80%90%E5%85%83%E6%BF%80%E6%B4%BB%E6%88%96%E9%97%A8%E6%8E%A7%22%5D%0A%20%20ACT%20--%3E%20DOWN%5B%22%E9%99%8D%E7%BB%B4%E5%9B%9E%20d%22%5D%0A%20%20DOWN%20--%3E%20ADD%5B%22%E4%BD%9C%E4%B8%BA%E5%A2%9E%E9%87%8F%E5%8A%A0%E5%9B%9E%E6%B5%81%22%5D%0A%20%20R%5B%22%E6%89%A9%E5%B1%95%E6%AF%94%20d_ff%20%E6%AF%94%20d%22%5D%20--%3E%20UP%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[o(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>扩展比不修复注意力的二次代价：那是长度 \\(n\\) 的问题，下一课路径里会标出，真正的公式在 SDPA 课序。也不修复词表内存：那是 \\(|V|d\\)。把 FFN 加宽当万能容量旋钮，会在训练激活显存上先爆。深度与宽度的替代——加块还是加 \\(d_{\\mathrm{ff}}\\)——经验上两者都有效，但加 \\(d_{\\mathrm{ff}}\\) 只增强逐位置，不加混合次数；加块则两种 \\(F\\) 的调用都增加。</p><p>下一课是本课程的最后一课：把嵌入、残差、两种子层、扩展比串成一块之内的信息跳转图，然后把注意力内核交给 <a href="/llm/sdpa">SDPA</a>。本课之后，默认「FFN 有一个大于 \\(d\\) 的中间宽，标准工作点是四倍或参数对齐后的 SwiGLU 宽」。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>FFN 在 \\(F\\) 内部把 \\(d\\) 扩到 \\(d_{\\mathrm{ff}}\\) 再投回，总线宽度不变。</li><li>Vaswani 的工作点是 \\(d_{\\mathrm{ff}}=4d\\)；门控变体常用 \\(\\approx\\frac{8}{3}d\\) 来对齐参数。</li><li>比较扩展比必须声明激活族；槽数 \\(d_{\\mathrm{ff}}\\) 是逐位置容量。</li><li>训练显存常由 \\(n\\times d_{\\mathrm{ff}}\\) 激活主导，与参数账不是同一条曲线。</li><li>加宽 FFN 不增加位置间混合次数；混合仍只发生在注意力。</li><li>出处：Vaswani et al., NeurIPS 2017；门控宽度记账见 Shazeer, <em>GLU Variants Improve Transformer</em>。</li></ul>',5))])}const N=d(h,[["render",p]]);export{A as __pageData,N as default};
